// lib/repertoire/data.ts
//
// GENERERAD FIL — andra inte for hand.
// Kalla: Poems-Worth-Memorising.pdf, via scripts/build-repertoire.mjs
//
// 762 dikter i 24 grupper. Har star BARA titel, upphovsperson och
// vilka arkiv som for texten. Ingen diktext finns i den har filen och
// ska aldrig laggas till: ungefar en tredjedel av listan ar fortfarande
// upphovsrattsskyddad, och att spara texten hade gjort appen till en
// olaglig kopia av ett halvt sekels poesi. Anvandaren hamtar texten
// sjalv, fran arkivet, och klistrar in den — precis som med vilket
// annat verk som helst.
//
// Loptnumret (`id`) ar identiteten. Det ar stabilt sa lange listan inte
// numreras om, och det ar vad Work.canonicalId pekar pa.

import type { ArchiveCode } from "./archives";

export interface RepertoireEntry {
  /** Loptnummer i listan, 1-762. */
  id:      number;
  title:   string;
  author:  string;
  /** En av de 116 i startuppsattningen. */
  starred: boolean;
  /** Arkiven som for just den har texten, i listans ordning. */
  links:   readonly ArchiveCode[];
}

export interface RepertoireGroup {
  /** Kebab-slug. Adress, medalj-id och border-id pa en gang. */
  id:      string;
  numeral: string;
  name:    string;
  blurb:   string;
  entries: readonly RepertoireEntry[];
}

